WITH a AS (SELECT 1 AS x)
WITH b AS (SELECT 2 AS y)
SELECT * FROM a, b;

SELECT name, ROW_NUMBER() OVER (ORDER BY salary DESC) AS rn
FROM employees
WHERE rn <= 5;

WITH totals AS (
  SELECT customer_id, SUM(total_amount) AS spent
  FROM orders GROUP BY customer_id
), stats AS (
  SELECT AVG(spent) AS avg_spent FROM totals
)
SELECT t.customer_id, t.spent
FROM totals t, stats s
WHERE t.spent > s.avg_spent
ORDER BY t.customer_id;

SELECT COUNT(*) FILTER (WHERE status = 'cancelled')
       / COUNT(*) * 100 AS cancel_pct
FROM orders;

WITH t(dept, n) AS (
  SELECT department, COUNT(*)
  FROM employees
  GROUP BY department
)
SELECT * FROM t;

SELECT region, SUM(revenue)
FROM sales_by_store
GROUP BY ROLLUP (region);

WITH RECURSIVE t AS (
  SELECT 1 AS n
  UNION ALL
  SELECT n + 1 FROM t
)
SELECT n FROM t LIMIT 5;
